     9→/// A widget for displaying a single training metric.
    10→pub struct MetricDisplay<'a> {
    11→    /// The metric value to display
    12→    value: String,
    13→    /// The unit label
    14→    unit: &'a str,
    15→    /// The metric name/label
    16→    label: &'a str,
    17→    /// Optional zone color
    18→    zone_color: Option<Color32>,
    19→    /// Size multiplier
    20→    size: MetricSize,
    21→}
    22→
    23→/// Size variants for metric display.
    24→#[derive(Debug, Clone, Copy, Default)]
    25→pub enum MetricSize {
    26→    /// Small metric (secondary display)
    27→    Small,
    28→    /// Medium metric (standard display)
    29→    #[default]
    30→    Medium,
    31→    /// Large metric (primary focus)
    32→    Large,
    33→}
    34→
    35→impl MetricSize {
    36→    fn value_size(&self) -> f32 {
    37→        match self {
    38→            MetricSize::Small => 28.0,
    39→            MetricSize::Medium => 42.0,
    40→            MetricSize::Large => 64.0,
    41→        }
    42→    }
    43→
    44→    fn unit_size(&self) -> f32 {
    45→        match self {
    46→            MetricSize::Small => 12.0,
    47→            MetricSize::Medium => 14.0,
    48→            MetricSize::Large => 18.0,
    49→        }
    50→    }
    51→
    52→    fn label_size(&self) -> f32 {
    53→        match self {
    54→            MetricSize::Small => 11.0,
    55→            MetricSize::Medium => 13.0,
    56→            MetricSize::Large => 15.0,
    57→        }
    58→    }
    59→}
    60→
    61→impl<'a> MetricDisplay<'a> {
    62→    /// Create a new metric display.
    63→    pub fn new(value: impl Into<String>, unit: &'a str, label: &'a str) -> Self {
    64→        Self {
    65→            value: value.into(),
    66→            unit,
    67→            label,
    68→            zone_color: None,
    69→            size: MetricSize::default(),
    70→        }
    71→    }
    72→
    73→    /// Create a metric display for power in watts.
    74→    pub fn power(watts: Option<u16>) -> Self {
    75→        let value = watts
    76→            .map(|w| w.to_string())
    77→            .unwrap_or_else(|| "--".to_string());
    78→        Self::new(value, "W", "Power")
    79→    }
    80→
    81→    /// Create a metric display for heart rate.
    82→    pub fn heart_rate(bpm: Option<u8>) -> Self {
    83→        let value = bpm
    84→            .map(|b| b.to_string())
    85→            .unwrap_or_else(|| "--".to_string());
    86→        Self::new(value, "bpm", "Heart Rate")
    87→    }
    88→
    89→    /// Create a metric display for cadence.
    90→    pub fn cadence(rpm: Option<u8>) -> Self {
    91→        let value = rpm
    92→            .map(|r| r.to_string())
    93→            .unwrap_or_else(|| "--".to_string());
    94→        Self::new(value, "rpm", "Cadence")
    95→    }
    96→
    97→    /// Create a metric display for speed.
    98→    pub fn speed(speed_kmh: Option<f32>) -> Self {
    99→        let value = speed_kmh
   100→            .map(|s| format!("{:.1}", s))
   101→            .unwrap_or_else(|| "--".to_string());
   102→        Self::new(value, "km/h", "Speed")
   103→    }
   104→
   105→    /// Create a metric display for speed with unit awareness.
   106→    /// T035: Unit-aware speed formatting.
   107→    pub fn speed_with_units(speed_mps: Option<f32>, units: Units) -> Self {
   108→        if let Some(mps) = speed_mps {
   109→            let (value, unit) = units.format_speed(mps as f64);
   110→            Self::new(format!("{:.1}", value), unit, "Speed")
   111→        } else {
   112→            let unit = match units {
   113→                Units::Metric => "km/h",
   114→                Units::Imperial => "mph",
   115→            };
   116→            Self::new("--".to_string(), unit, "Speed")
   117→        }
   118→    }
   119→
   120→    /// Create a metric display for distance.
   121→    pub fn distance(meters: f64) -> Self {
   122→        let km = meters / 1000.0;
   123→        Self::new(format!("{:.2}", km), "km", "Distance")
   124→    }
   125→
   126→    /// Create a metric display for distance with unit awareness.
   127→    /// T035: Unit-aware distance formatting.
   128→    pub fn distance_with_units(meters: f64, units: Units) -> Self {
   129→        let (value, unit) = units.format_distance(meters);
   130→        Self::new(format!("{:.2}", value), unit, "Distance")
   131→    }
   132→
   133→    /// Create a metric display for elevation with unit awareness.
   134→    /// T035: Unit-aware elevation formatting.
   135→    pub fn elevation_with_units(meters: f64, units: Units) -> Self {
   136→        let (value, unit) = units.format_elevation(meters);
   137→        Self::new(format!("{:.0}", value), unit, "Elevation")
   138→    }
   139→
   140→    /// Create a metric display for weight with unit awareness.
   141→    /// T035: Unit-aware weight formatting.
   142→    pub fn weight_with_units(kg: f64, units: Units) -> Self {
   143→        let (value, unit) = units.format_weight(kg);
   144→        Self::new(format!("{:.1}", value), unit, "Weight")
   145→    }
   146→
   147→    /// Create a metric display for duration.
   148→    pub fn duration(seconds: u32) -> Self {
   149→        let hours = seconds / 3600;
   150→        let minutes = (seconds % 3600) / 60;
   151→        let secs = seconds % 60;
   152→
   153→        let value = if hours > 0 {
   154→            format!("{}:{:02}:{:02}", hours, minutes, secs)
   155→        } else {
   156→            format!("{}:{:02}", minutes, secs)
   157→        };
   158→
   159→        Self::new(value, "", "Time")
   160→    }
   161→
   162→    /// Set a zone color for the metric.
   163→    pub fn with_zone_color(mut self, color: Color32) -> Self {
   164→        self.zone_color = Some(color);
   165→        self
   166→    }
   167→
   168→    /// Set the display size.
   169→    pub fn with_size(mut self, size: MetricSize) -> Self {
   170→        self.size = size;
   171→        self
   172→    }
   173→
   174→    /// Render the metric display.
   175→    pub fn show(self, ui: &mut Ui) {
   176→        let min_size = match self.size {
   177→            MetricSize::Small => Vec2::new(80.0, 60.0),
   178→            MetricSize::Medium => Vec2::new(120.0, 80.0),
   179→            MetricSize::Large => Vec2::new(180.0, 100.0),
   180→        };
   181→
   182→        egui::Frame::new().inner_margin(8.0).show(ui, |ui| {
   183→            ui.set_min_size(min_size);
   184→
   185→            ui.with_layout(Layout::top_down(Align::Center), |ui| {
   186→                // Label
   187→                ui.label(
   188→                    RichText::new(self.label)
   189→                        .size(self.size.label_size())
   190→                        .weak(),
   191→                );
   192→
   193→                ui.add_space(4.0);
   194→
   195→                // Value with optional zone color
   196→                let value_text = RichText::new(&self.value)
   197→                    .size(self.size.value_size())
   198→                    .strong();
   199→
   200→                let value_text = if let Some(color) = self.zone_color {
   201→                    value_text.color(color)
   202→                } else {
   203→                    value_text
   204→                };
   205→
   206→                // Value and unit on same line
   207→                ui.horizontal(|ui| {
   208→                    ui.label(value_text);
   209→                    if !self.unit.is_empty() {
   210→                        ui.label(RichText::new(self.unit).size(self.size.unit_size()).weak());
   211→                    }
   212→                });
   213→            });
   214→        });
   215→    }
   216→}
